-- this migration installs model presets, to make them available for quick deployment.
-- it adds compute assets, environment assets and model assets that use the the compute and environment ones.
-- the assets are added with the system scope, so they are available to all the tenants in the system.

-- using this format of DO/BEGIN/END in order to be able to declare variables and use them in multiple places

DO $$
DECLARE
    CREATED_AT timestamp := now();
    CREATED_BY text := 'Run:ai';

    DOCKER_IMAGE text := 'gcr.io/run-ai-demo/quickstart-inference';

    ENV_VARS jsonb := '[{"name": "PATH_PREFIX","value": "/${RUNAI_PROJECT}/${RUNAI_JOB_NAME}"}]';

    CONNECTIONS jsonb := '[{"name": "Chatbot UI", "internalToolInfo": {"toolType": "chatbot-ui", "containerPort": 3000, "connectionType": "ExternalUrl", "externalUrlInfo": {}}}]';

    LICENSE_META text := 'This inference workload uses <a target="_blank" href="https://ai.meta.com/resources/models-and-libraries/llama-downloads/">Llama2</a>, which is a gated model.<div>Your use of this inference workload is conditioned on continued compliance with Meta''s <a target="_blank" href="https://ai.meta.com/llama/use-policy/">Llama2 Use Policy</a>. You will indemnify and hold harmless Run.ai from and against any claim by any third party arising out of or related to your use of this workload or violation of the aforementioned Use Policy. Run.ai disclaims all warranties in respect of the workload. Your use of this workload and any output thereof is at your own risk. Run.ai has no liability with respect to this workload, or your use of any output thereof.</div><div>If you do not agree with the foregoing disclaimers and limitations then do not use this workload.</div>';

    THUMBNAIL_FALCON_7B  bytea := 'data:image/png;base64,';
    THUMBNAIL_FALCON_40B bytea := 'data:image/png;base64,';
    THUMBNAIL_LLAMA_7B   bytea := 'data:image/png;base64,';
    THUMBNAIL_LLAMA_13B  bytea := 'data:image/png;base64,';

    uuid_compute_gpu_memory_16g uuid := '3ab6826a-2123-4b34-a686-64cdf47388ac';
    uuid_compute_gpu_memory_20g uuid := 'ecbb7a29-5e49-40f3-8145-15c2ffa4f710';
    uuid_compute_gpu_memory_40g uuid := 'f8f08816-53d9-47da-b3c7-2f003b175dc4';
    uuid_compute_gpu_memory_80g uuid := '07e99ad0-aa2f-4dd2-9385-e4a4b2ddc207';
    uuid_environment_falcon_7b uuid := '514b77df-0869-468d-94ce-5a2c7b5dc1bb';
    uuid_environment_falcon_40b uuid := 'edafbeda-9bf5-4b8f-8483-40f8d006b81b';
    uuid_environment_llama_2_7b uuid := 'eed318a0-4e7c-4ccf-8af3-79d28e733f50';
    uuid_environment_llama_2_13b uuid := 'bf571c89-e258-4954-9c09-93c59f36ace5';
    uuid_model_falcon_7b uuid := 'c6accd0c-3652-4975-ba11-7c9e3e05c7dd';
    uuid_model_falcon_40b uuid := 'b074bd87-6c31-41fa-89f2-16b470d46d29';
    uuid_model_llama_2_7b uuid := '45ab1c3e-df3b-4b8e-819e-b477fac1302f';
    uuid_model_llama_2_13b uuid := '5be388f5-2420-4aaa-b63d-73ee65b69211';
BEGIN
    BEGIN
        INSERT INTO assets_metadata ("id", "kind", "scope", "name", "created_by", "created_at", "updated_by", "updated_at") VALUES
            (uuid_compute_gpu_memory_16g, 'compute', 'system', 'gpu-memory-16g', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_compute_gpu_memory_20g, 'compute', 'system', 'gpu-memory-20g', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_compute_gpu_memory_40g, 'compute', 'system', 'gpu-memory-40g', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_compute_gpu_memory_80g, 'compute', 'system', 'gpu-memory-80g', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_environment_falcon_7b, 'environment', 'system', 'falcon-7b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_environment_falcon_40b, 'environment', 'system', 'falcon-40b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_environment_llama_2_7b, 'environment', 'system', 'llama-2-7b-chat-hf', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_environment_llama_2_13b, 'environment', 'system', 'llama-2-13b-chat-hf', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_falcon_7b, 'model', 'system', 'falcon-7b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_falcon_40b, 'model', 'system', 'falcon-40b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_llama_2_7b, 'model', 'system', 'llama-2-7b-chat-hf', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_llama_2_13b, 'model', 'system', 'llama-2-13b-chat-hf', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT);

        INSERT INTO assets_compute ("asset_id", "cpu_core_request", "cpu_memory_request", "gpu_request_type", "gpu_memory_request", "gpu_portion_request", "gpu_devices_request") VALUES
            (uuid_compute_gpu_memory_16g, 1, '16G', 'memory', '16G', NULL, 1),
            (uuid_compute_gpu_memory_20g, 1, '20G', 'memory', '20G', NULL, 1),
            (uuid_compute_gpu_memory_40g, 1, '40G', 'memory', '40G', NULL, 1),
            (uuid_compute_gpu_memory_80g, 1, '80G', 'memory', '80G', NULL, 1);

        INSERT INTO assets_environment ("asset_id", "image", "image_pull_policy", "environment_variables", "connections") VALUES
            (uuid_environment_falcon_7b, DOCKER_IMAGE || ':falcon-7b-instruct', 'IfNotPresent', ENV_VARS, CONNECTIONS),
            (uuid_environment_falcon_40b, DOCKER_IMAGE || ':falcon-40b-instruct', 'IfNotPresent', ENV_VARS, CONNECTIONS),
            (uuid_environment_llama_2_7b, DOCKER_IMAGE || ':Llama-2-7b-chat-hf', 'IfNotPresent', ENV_VARS, CONNECTIONS),
            (uuid_environment_llama_2_13b, DOCKER_IMAGE || ':Llama-2-13b-chat-hf', 'IfNotPresent', ENV_VARS, CONNECTIONS);

        INSERT INTO assets_supported_workload_types ("asset_id", "workspace", "training", "distributed", "inference") VALUES
            (uuid_environment_falcon_7b, FALSE, FALSE, FALSE, TRUE),
            (uuid_environment_falcon_40b, FALSE, FALSE, FALSE, TRUE),
            (uuid_environment_llama_2_7b, FALSE, FALSE, FALSE, TRUE),
            (uuid_environment_llama_2_13b, FALSE, FALSE, FALSE, TRUE);

        INSERT INTO assets_model ("asset_id", "title", "description", "thumbnail", "huggingface_id", "license", "compute_asset_id", "environment_asset_id") VALUES
            (uuid_model_falcon_7b, 'Falcon Instruct 7B',
             'TII''s Falcon generative text model of 7B parameters. Pre-trained, fine-tuned, and optimized for dialog cases.',
             THUMBNAIL_FALCON_7B, 'tiiuae/falcon-7b-instruct', '', uuid_compute_gpu_memory_16g, uuid_environment_falcon_7b),
            (uuid_model_falcon_40b, 'Falcon Instruct 40B',
             'TII''s Falcon generative text model of 40B parameters. Pre-trained, fine-tuned, and optimized for dialog cases.',
             THUMBNAIL_FALCON_40B, 'tiiuae/falcon-40b-instruct', '', uuid_compute_gpu_memory_80g, uuid_environment_falcon_40b),
            (uuid_model_llama_2_7b, 'Llama-2 Chat 7B',
             'Meta''s Llama 2 generative text model of 7B parameters. Pre-trained, fine-tuned, and optimized for dialog cases.',
             THUMBNAIL_LLAMA_7B, 'meta-llama/Llama-2-7b-chat-hf', LICENSE_META, uuid_compute_gpu_memory_16g, uuid_environment_llama_2_7b),
            (uuid_model_llama_2_13b, 'Llama-2 Chat 13B',
             'Meta''s Llama 2 generative text model of 13B parameters. Pre-trained, fine-tuned, and optimized for dialog cases.',
             THUMBNAIL_LLAMA_13B, 'meta-llama/Llama-2-13b-chat-hf', LICENSE_META, uuid_compute_gpu_memory_40g, uuid_environment_llama_2_13b);
    EXCEPTION
        WHEN unique_violation THEN
            -- do nothing, already exists
            RAISE NOTICE 'Assets already exist, skipping';
    END;
END $$;
